/* Vygenerováno z data/cvicne-otazky/kapitola-*.json, neupravovat ručně. */
window.VZOROVA_ZKOUSKA = {"sada":"cvicna-4","nazev":"Cvičná zkouška 4","oficialni":false,"otazky":[{"id":"CG-1.1.1-03","n":1,"lo":"GenAI-1.1.1","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which statement about generative AI is CORRECT?<\/p>","m":["It generates content by evaluating logical rules defined by domain experts.","It only assigns existing data items to predefined categories.","It uses deep learning techniques to create new content based on patterns learned from training data.","It requires a separate training phase before it can be used for each test task."],"vys":{"a":"Incorrect. Logical rules defined by experts describe symbolic AI (syllabus 1.1.1).","b":"Incorrect. Assigning data to categories is a typical classification task, e.g. defect categorization with classical machine learning, not content generation (syllabus 1.1.1).","c":"Correct. Generative AI uses deep learning to create new text, images or code by mimicking patterns from its training data (syllabus 1.1.1).","d":"Incorrect. The syllabus highlights that pre-trained models can be applied directly without an additional training phase (syllabus 1.1.1)."},"obecne":"Generative AI = deep learning + creation of new content."},"cz":{"q":"<p>Které tvrzení o generativní AI je SPRÁVNÉ?<\/p>","m":["Vytváří obsah vyhodnocováním logických pravidel, která definovali odborníci.","Pouze zařazuje existující data do předem daných kategorií.","Používá techniky hlubokého učení a vytváří nový obsah podle vzorců naučených z trénovacích dat.","Před použitím pro každou testovací úlohu vyžaduje samostatnou fázi trénování."],"vys":{"a":"Nesprávně. Logická pravidla od odborníků popisují symbolickou AI (sylabus 1.1.1).","b":"Nesprávně. Zařazování dat do kategorií je klasifikační úloha, například kategorizace defektů klasickým ML, ne tvorba obsahu (sylabus 1.1.1).","c":"Správně. Generativní AI používá hluboké učení a vytváří nový text, obrázky nebo kód napodobením vzorců z trénovacích dat (sylabus 1.1.1).","d":"Nesprávně. Sylabus zdůrazňuje, že předtrénované modely lze použít přímo bez další fáze trénování (sylabus 1.1.1)."},"obecne":"Generativní AI = hluboké učení + tvorba nového obsahu."},"kap":{"c":"1.1.1","nazev":"1.1.1 Spektrum AI: symbolická AI, klasické strojové učení, hluboké učení a generativní AI","href":"kapitola-1/vyklad.html#oddil-1-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.2-08","n":2,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":2,"ok":[0,2],"en":{"q":"<p>Which TWO statements about tokens and tokenization are CORRECT?<\/p>","m":["The number of tokens in an input determines how much of the context window it uses.","Each token always corresponds to exactly one word.","Punctuation marks and special characters can be represented as separate tokens.","Tokens are vectors that capture the semantic meaning of words.","Tokenization takes place after the model has generated its response."],"vys":{"a":"Correct. The context window is measured in tokens (syllabus 1.1.2).","b":"Incorrect. A token can be a character, a sub-word or a word (syllabus 1.1.2).","c":"Correct. Tokenization breaks text into units that may be as small as a character, including punctuation (syllabus 1.1.2).","d":"Incorrect. Vectors that capture meaning are embeddings, not tokens (syllabus 1.1.2).","e":"Incorrect. The model first tokenizes the input so that it can process it (syllabus 1.1.2)."},"obecne":"Tokens are units of text; embeddings are their vectors; the context window is measured in tokens."},"cz":{"q":"<p>Která DVĚ tvrzení o tokenech a tokenizaci jsou SPRÁVNÁ?<\/p>","m":["Počet tokenů ve vstupu určuje, jakou část kontextového okna vstup zabere.","Každý token vždy odpovídá právě jednomu slovu.","Interpunkce a speciální znaky mohou být samostatnými tokeny.","Tokeny jsou vektory, které zachycují význam slov.","Tokenizace probíhá až poté, co model vygeneruje odpověď."],"vys":{"a":"Správně. Kontextové okno se měří v tokenech (sylabus 1.1.2).","b":"Nesprávně. Token může být znak, část slova nebo slovo (sylabus 1.1.2).","c":"Správně. Tokenizace dělí text na jednotky, které mohou být malé jako jeden znak, včetně interpunkce (sylabus 1.1.2).","d":"Nesprávně. Vektory s významem jsou embeddingy, ne tokeny (sylabus 1.1.2).","e":"Nesprávně. Model vstup nejdřív tokenizuje, aby ho mohl zpracovat (sylabus 1.1.2)."},"obecne":"Tokeny jsou jednotky textu, embeddingy jejich vektory, kontextové okno se měří v tokenech."},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.2-07","n":3,"lo":"GenAI-1.1.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>In which situation is a small language model (SLM) the MOST appropriate choice instead of a large language model?<\/p>","m":["The team needs a lightweight model for one focused task, such as classifying log lines on a server with limited computing resources.","The team needs to process screenshots, audio recordings and text in one prompt.","The team needs the largest possible context window to analyse complete specifications.","The team needs high-quality answers to open questions from many different domains."],"vys":{"a":"Correct. SLMs have fewer parameters and are designed for lightweight and focused GenAI solutions (syllabus 1.1.2).","b":"Incorrect. This requires a multimodal model; being small is not the relevant property (syllabus 1.1.4).","c":"Incorrect. Nothing in the syllabus links SLMs to large context windows; their benefit is being compact and focused (syllabus 1.1.2).","d":"Incorrect. Broad, multi-domain tasks favour LLMs with more parameters and wider training (syllabus 1.1.2)."},"obecne":"SLM = fewer parameters, lightweight, focused."},"cz":{"q":"<p>Ve které situaci je malý jazykový model (SLM) NEJVHODNĚJŠÍ volbou místo velkého jazykového modelu?<\/p>","m":["Tým potřebuje lehký model pro jednu zaměřenou úlohu, například třídění řádků logu na serveru s omezeným výpočetním výkonem.","Tým potřebuje v jednom promptu zpracovat snímky obrazovky, zvukové nahrávky a text.","Tým potřebuje co největší kontextové okno pro analýzu kompletních specifikací.","Tým potřebuje kvalitní odpovědi na otevřené otázky z mnoha různých oborů."],"vys":{"a":"Správně. SLM mají méně parametrů a jsou navržené jako lehká a zaměřená řešení GenAI (sylabus 1.1.2).","b":"Nesprávně. To vyžaduje multimodální model. Velikost modelu tu není podstatná vlastnost (sylabus 1.1.4).","c":"Nesprávně. Sylabus SLM s velkým kontextovým oknem nespojuje. Jejich přínos je kompaktnost a zaměření (sylabus 1.1.2).","d":"Nesprávně. Široké úlohy napříč obory svědčí LLM s víc parametry a širším tréninkem (sylabus 1.1.2)."},"obecne":"SLM = méně parametrů, lehké, zaměřené řešení."},"kap":{"c":"1.1.2","nazev":"1.1.2 Základy generativní AI a LLM","href":"kapitola-1/vyklad.html#oddil-1-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.3-01","n":4,"lo":"GenAI-1.1.3","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A test team needs an LLM to generate test data records that follow an exact JSON schema with the team's field naming conventions. The task requires no complex analysis. Which type of LLM is the BEST fit?<\/p>","m":["Foundation LLM","Instruction-tuned LLM","Vision-language model","Reasoning LLM"],"vys":{"a":"Incorrect. Foundation LLMs typically need further adaptation to meet specific task requirements such as a fixed format (syllabus 1.1.3).","b":"Correct. Instruction-tuned LLMs are optimised for task adherence and instruction following, which suits strict format requirements (syllabus 1.1.3).","c":"Incorrect. The task involves no visual input (syllabus 1.1.4).","d":"Incorrect. Reasoning LLMs target multi-step problem-solving; this task mainly needs precise instruction following (syllabus 1.1.3)."},"obecne":"Exact format and clear instructions point to an instruction-tuned LLM."},"cz":{"q":"<p>Testovací tým potřebuje, aby LLM vygeneroval záznamy testovacích dat přesně podle schématu JSON s konvencemi pojmenování polí, které tým používá. Úloha nevyžaduje složitou analýzu. Který typ LLM se hodí NEJLÉPE?<\/p>","m":["Základní (foundation) LLM","LLM vyladěný na instrukce","Model pro obraz a jazyk","Uvažující (reasoning) LLM"],"vys":{"a":"Nesprávně. Základní LLM obvykle potřebují další přizpůsobení, aby splnily konkrétní požadavky, jako je pevný formát (sylabus 1.1.3).","b":"Správně. LLM vyladěné na instrukce jsou optimalizované na dodržení úlohy a plnění instrukcí, což odpovídá přísným požadavkům na formát (sylabus 1.1.3).","c":"Nesprávně. Úloha nemá žádný vizuální vstup (sylabus 1.1.4).","d":"Nesprávně. Uvažující LLM míří na řešení problémů o více krocích. Tady jde hlavně o přesné plnění instrukcí (sylabus 1.1.3)."},"obecne":"Přesný formát a jasné instrukce vedou na LLM vyladěný na instrukce."},"kap":{"c":"1.1.3","nazev":"1.1.3 Základní, instrukční a uvažující LLM","href":"kapitola-1/vyklad.html#oddil-1-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.1.4-03","n":5,"lo":"GenAI-1.1.4","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following is a typical task of vision-language models?<\/p>","m":["Generating unit tests from source code without any visual input.","Transcribing audio recordings of review meetings into minutes.","Answering a question about the content of a screenshot, such as whether an error message is visible.","Predicting defect-prone modules from code metrics."],"vys":{"a":"Incorrect. A text-only task does not need a vision-language model (syllabus 1.1.4).","b":"Incorrect. Audio transcription involves the audio modality, which is outside the visual and textual focus of vision-language models (syllabus 1.1.4).","c":"Correct. Visual question answering is one of the tasks the syllabus lists for vision-language models (syllabus 1.1.4).","d":"Incorrect. Prediction from code metrics is a typical use of classical machine learning (syllabus 1.1.1)."},"obecne":"Typical VLM tasks: image captioning, visual question answering, text and image consistency."},"cz":{"q":"<p>Která z následujících úloh je typická pro modely pro obraz a jazyk?<\/p>","m":["Generování jednotkových testů ze zdrojového kódu bez vizuálního vstupu.","Přepis zvukových nahrávek z revizních schůzek do zápisu.","Odpověď na otázku k obsahu snímku obrazovky, například zda je vidět chybová hláška.","Předpověď modulů náchylných k defektům z metrik kódu."],"vys":{"a":"Nesprávně. Čistě textová úloha model pro obraz a jazyk nepotřebuje (sylabus 1.1.4).","b":"Nesprávně. Přepis zvuku pracuje se zvukovou modalitou, která je mimo zaměření modelů pro obraz a jazyk (sylabus 1.1.4).","c":"Správně. Odpovídání na otázky k obrázku (visual question answering) je jedna z úloh, které sylabus u těchto modelů uvádí (sylabus 1.1.4).","d":"Nesprávně. Předpověď z metrik kódu je typické použití klasického strojového učení (sylabus 1.1.1)."},"obecne":"Typické úlohy VLM: popis obrázku, odpovídání na otázky k obrázku, soulad textu a obrazu."},"kap":{"c":"1.1.4","nazev":"1.1.4 Multimodální LLM a modely pro obraz a jazyk","href":"kapitola-1/vyklad.html#oddil-1-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.1-04","n":6,"lo":"GenAI-1.2.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A tester gives an LLM an acceptance criterion: 'The system shall respond quickly when the user submits the form.' Which response from the LLM is an example of requirements analysis and improvement?<\/p>","m":["A Playwright script that submits the form and measures the response time.","A test summary report stating that all form tests have passed.","A set of 20 form submissions with random input values.","A note that 'quickly' is ambiguous, with a question asking the product owner for a measurable response time limit."],"vys":{"a":"Incorrect. Writing a script is test automation support (syllabus 1.2.1).","b":"Incorrect. A summary report is testware creation or test result analysis (syllabus 1.2.1).","c":"Incorrect. Creating input values is test data generation (syllabus 1.2.1).","d":"Correct. Identifying ambiguity and generating a clarifying question for stakeholders is requirements analysis and improvement (syllabus 1.2.1)."},"obecne":"Requirements analysis: ambiguities, inconsistencies, missing information, clarifying questions."},"cz":{"q":"<p>Tester dá LLM akceptační kritérium: 'Systém musí po odeslání formuláře reagovat rychle.' Která odpověď LLM je příkladem analýzy a zlepšování požadavků?<\/p>","m":["Skript v Playwright, který formulář odešle a změří dobu odezvy.","Report o testování s konstatováním, že všechny testy formuláře prošly.","Sada 20 odeslání formuláře s náhodnými vstupními hodnotami.","Upozornění, že slovo 'rychle' je nejednoznačné, a otázka pro product ownera na měřitelný limit doby odezvy."],"vys":{"a":"Nesprávně. Psaní skriptu je podpora automatizace testů (sylabus 1.2.1).","b":"Nesprávně. Report je tvorba testwaru nebo analýza výsledků testů (sylabus 1.2.1).","c":"Nesprávně. Tvorba vstupních hodnot je generování testovacích dat (sylabus 1.2.1).","d":"Správně. Odhalení nejednoznačnosti a otázka pro stakeholdera jsou analýza a zlepšování požadavků (sylabus 1.2.1)."},"obecne":"Analýza požadavků: nejednoznačnosti, rozpory, chybějící informace, otázky k vyjasnění."},"kap":{"c":"1.2.1","nazev":"1.2.1 Hlavní schopnosti LLM pro testovací úlohy","href":"kapitola-1/vyklad.html#oddil-1-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-1.2.2-04","n":7,"lo":"GenAI-1.2.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>A test team wants every new defect report in its test management tool to be automatically classified and linked to similar existing defects, without anyone opening a chat window. Which approach fits BEST?<\/p>","m":["An LLM-powered testing application integrated into the test management tool via an API","An AI chatbot that testers consult when they have time","A foundation LLM used without any integration","A rule-based script that matches keywords in defect titles"],"vys":{"a":"Correct. LLM-powered testing applications integrate LLMs via APIs to automate well-defined tasks such as defect analysis (syllabus 1.2.2).","b":"Incorrect. A chatbot requires a person to start each interaction; the team wants automation (syllabus 1.2.2).","c":"Incorrect. A model on its own is not integrated into the tool and does not perform the task automatically (syllabus 1.2.2).","d":"Incorrect. Keyword matching is a rule-based approach without the language capabilities of LLMs (syllabus 1.1.1)."},"obecne":"Automated, repeated, well-defined tasks inside a tool point to an LLM-powered testing application."},"cz":{"q":"<p>Testovací tým chce, aby se každý nový report o defektu v nástroji pro správu testů automaticky zařadil do kategorie a propojil s podobnými existujícími defekty, aniž by kdokoli otevíral chatovací okno. Který přístup se hodí NEJLÉPE?<\/p>","m":["Testovací aplikace na LLM integrovaná do nástroje pro správu testů přes API","AI chatbot, kterého se testeři zeptají, když mají čas","Základní LLM použitý bez jakékoli integrace","Pravidlový skript, který hledá klíčová slova v názvech defektů"],"vys":{"a":"Správně. Testovací aplikace na LLM integrují LLM přes API a automatizují vymezené úlohy, jako je analýza defektů (sylabus 1.2.2).","b":"Nesprávně. Chatbot vyžaduje, aby každou interakci zahájil člověk. Tým chce automatizaci (sylabus 1.2.2).","c":"Nesprávně. Samotný model není integrovaný do nástroje a úlohu automaticky neprovádí (sylabus 1.2.2).","d":"Nesprávně. Hledání klíčových slov je pravidlový přístup bez jazykových schopností LLM (sylabus 1.1.1)."},"obecne":"Automatizované, opakované a vymezené úlohy uvnitř nástroje vedou na testovací aplikaci na LLM."},"kap":{"c":"1.2.2","nazev":"1.2.2 AI chatboti a testovací aplikace postavené na LLM","href":"kapitola-1/vyklad.html#oddil-1-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.1-09","n":8,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following pairs of prompt component and example is correct?<\/p>","m":["Context: “return the findings as JSON with the fields id, severity and description”","Role: “the system under test is a payment gateway used by 300 merchants”","Input data: “the attached performance test results and server monitoring logs from last night”","Constraints: “act as a test automation engineer”"],"vys":{"a":"Incorrect. This is the output format (syllabus 2.1.1).","b":"Incorrect. This describes the test object, which is context (syllabus 2.1.1).","c":"Correct. Results and logs are material for the task, so they are input data (syllabus 2.1.1).","d":"Incorrect. This is a role (syllabus 2.1.1)."},"obecne":"Each component answers a different question: who answers (role), about what (context), what to do (instruction), with what (input data), under which rules (constraints) and in which form (output format)."},"cz":{"q":"<p>Která z následujících dvojic komponenta promptu a příklad je správná?<\/p>","m":["Kontext: „nálezy vrať jako JSON s poli id, severity a description“","Role: „testovaný systém je platební brána, kterou používá 300 obchodníků“","Vstupní data: „přiložené výsledky výkonnostních testů a logy z monitoringu serverů z poslední noci“","Omezení: „jednej jako inženýr automatizace testů“"],"vys":{"a":"Špatně. To je formát výstupu (sylabus 2.1.1).","b":"Špatně. Popisuje testovaný objekt, tedy kontext (sylabus 2.1.1).","c":"Správně. Výsledky a logy jsou materiál pro úlohu, tedy vstupní data (sylabus 2.1.1).","d":"Špatně. To je role (sylabus 2.1.1)."},"obecne":"Každá komponenta odpovídá na jinou otázku: kdo odpovídá (role), o čem (kontext), co udělat (instrukce), s čím (vstupní data), podle jakých pravidel (omezení) a v jaké podobě (formát výstupu)."},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.1-07","n":9,"lo":"GenAI-2.1.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following is the BEST example of an <b>instruction<\/b> in a structured prompt for test design?<\/p>","m":["“Present the result as a table with ID, input and expected result.”","“The transfer feature is part of the mobile banking app for private clients.”","“Derive one test case for each boundary value of the transfer amount field described below.”","“Maybe you could have a look at the transfer feature if you have time.”"],"vys":{"a":"Incorrect. This is the output format (syllabus 2.1.1).","b":"Incorrect. This is context, not an instruction (syllabus 2.1.1).","c":"Correct. It is clear, imperative and concise and states the task and its requirement (syllabus 2.1.1).","d":"Incorrect. It is not imperative and does not state a clear task (syllabus 2.1.1)."},"obecne":"Instructions are clear, imperative and concise directives that include a task description and relevant requirements."},"cz":{"q":"<p>Co z následujícího je NEJLEPŠÍM příkladem <b>instrukce<\/b> ve strukturovaném promptu pro návrh testů?<\/p>","m":["„Výsledek uveď jako tabulku s ID, vstupem a očekávaným výsledkem.“","„Funkce převodu je součástí mobilního bankovnictví pro fyzické osoby.“","„Pro každou hraniční hodnotu pole částka převodu popsaného níže odvoď jeden testovací případ.“","„Možná by ses mohl podívat na funkci převodu, pokud budeš mít čas.“"],"vys":{"a":"Špatně. To je formát výstupu (sylabus 2.1.1).","b":"Špatně. To je kontext, ne instrukce (sylabus 2.1.1).","c":"Správně. Je jasná, v rozkazovacím způsobu, stručná a uvádí úlohu i požadavek (sylabus 2.1.1).","d":"Špatně. Není v rozkazovacím způsobu a neříká jasnou úlohu (sylabus 2.1.1)."},"obecne":"Instrukce je jasný, stručný pokyn v rozkazovacím způsobu s popisem úlohy a podstatnými požadavky."},"kap":{"c":"2.1.1","nazev":"2.1.1 Struktura promptu pro testování","href":"kapitola-2/vyklad.html#oddil-2-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.2-04","n":10,"lo":"GenAI-2.1.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>What is the difference between zero-shot and one-shot prompting?<\/p>","m":["A zero-shot prompt has no structure; a one-shot prompt has all six components.","A zero-shot prompt is sent without a system prompt; a one-shot prompt is sent with one system prompt.","A zero-shot prompt gets no answer on the first attempt; a one-shot prompt gets an answer after one retry.","A zero-shot prompt contains no example and relies on the model's pre-existing knowledge; a one-shot prompt contains exactly one example of the expected result."],"vys":{"a":"Incorrect. A zero-shot prompt can be fully structured; it just has no example (syllabus 2.1.1, 2.1.2).","b":"Incorrect. The terms refer to examples in the prompt, not to system prompts (syllabus 2.1.2, 2.1.3).","c":"Incorrect. “Shot” means an example, not an attempt (syllabus 2.1.2).","d":"Correct. This matches syllabus 2.1.2."},"obecne":"The number of examples distinguishes zero-shot (none), one-shot (one) and few-shot (several)."},"cz":{"q":"<p>Jaký je rozdíl mezi zero-shot a one-shot promptingem?<\/p>","m":["Zero-shot prompt nemá strukturu; one-shot prompt má všech šest komponent.","Zero-shot prompt se posílá bez systémového promptu; one-shot prompt s jedním systémovým promptem.","Zero-shot prompt nedostane odpověď na první pokus; one-shot prompt ji dostane po jednom opakování.","Zero-shot prompt neobsahuje žádný příklad a spoléhá na znalosti modelu; one-shot prompt obsahuje právě jeden příklad očekávaného výsledku."],"vys":{"a":"Špatně. Zero-shot prompt může být plně strukturovaný, jen nemá příklad (sylabus 2.1.1, 2.1.2).","b":"Špatně. Pojmy se týkají příkladů v promptu, ne systémových promptů (sylabus 2.1.2, 2.1.3).","c":"Špatně. „Shot“ znamená příklad, ne pokus (sylabus 2.1.2).","d":"Správně. Odpovídá sylabu 2.1.2."},"obecne":"Počet příkladů rozlišuje zero-shot (žádný), one-shot (jeden) a few-shot (několik)."},"kap":{"c":"2.1.2","nazev":"2.1.2 Základní techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.1.3-03","n":11,"lo":"GenAI-2.1.3","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>The system prompt of a test assistant says that test cases must always be returned with the fields ID, preconditions, steps and expected result. A tester sends the user prompt: “Create test cases for changing the card limit.” What is the expected behavior?<\/p>","m":["The model creates test cases for the card limit and uses the fields defined in the system prompt, because it considers both prompts together.","The model ignores the field definition because the user prompt does not repeat it.","The model replaces the system prompt with the user prompt for the rest of the session.","The model asks the user to confirm the system prompt before answering."],"vys":{"a":"Correct. The LLM generates responses by considering the unchanging system prompt and the current user prompt together (syllabus 2.1.3).","b":"Incorrect. Rules in the system prompt apply to the whole conversation without repetition (syllabus 2.1.3).","c":"Incorrect. The system prompt stays constant throughout the interaction session (syllabus 2.1.3).","d":"Incorrect. The system prompt is not something the user confirms; it is predefined (syllabus 2.1.3)."},"obecne":"Typical usage: the system prompt is set once at the start, then successive user prompts are sent; both are considered for each response."},"cz":{"q":"<p>Systémový prompt testovacího asistenta říká, že testovací případy se mají vždy vracet s poli ID, předpoklady, kroky a očekávaný výsledek. Tester pošle uživatelský prompt: „Vytvoř testovací případy pro změnu limitu karty.“ Jaké chování se očekává?<\/p>","m":["Model vytvoří testovací případy pro limit karty s poli ze systémového promptu, protože bere v úvahu oba prompty zároveň.","Model definici polí ignoruje, protože ji uživatelský prompt neopakuje.","Model po zbytek session nahradí systémový prompt uživatelským.","Model před odpovědí požádá uživatele o potvrzení systémového promptu."],"vys":{"a":"Správně. Model tvoří odpověď s ohledem na neměnný systémový prompt i aktuální uživatelský prompt (sylabus 2.1.3).","b":"Špatně. Pravidla ze systémového promptu platí pro celou konverzaci i bez opakování (sylabus 2.1.3).","c":"Špatně. Systémový prompt zůstává po celou session stejný (sylabus 2.1.3).","d":"Špatně. Systémový prompt uživatel nepotvrzuje, je předem daný (sylabus 2.1.3)."},"obecne":"Typický postup: systémový prompt se nastaví jednou na začátku, pak přicházejí uživatelské prompty; pro každou odpověď se berou v úvahu oba."},"kap":{"c":"2.1.3","nazev":"2.1.3 Systémový prompt a uživatelský prompt","href":"kapitola-2/vyklad.html#oddil-2-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.1-01","n":12,"lo":"GenAI-2.2.1","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>A product owner of an online shop delivers a user story with acceptance criteria for a loyalty program and admits that some criteria are vague. You want to use prompt chaining with human verification to make the acceptance criteria well-formed and actionable. Which sequence of prompts is MOST appropriate?<\/p><ol><li>Ask the LLM to evaluate whether each criterion is testable and to rewrite untestable ones.<\/li><li>Ask the LLM to identify ambiguous wording in the story and criteria.<\/li><li>Ask the LLM to evaluate whether the criteria cover the story completely and propose missing ones.<\/li><\/ol><p>After each step you verify and correct the result before the next prompt.<\/p>","m":["All three steps in one prompt, followed by one final review","2 – 1 – 3","1 – 2 – 3","3 – 2 – 1"],"vys":{"a":"Incorrect. This is not prompt chaining; intermediate results are not verified (syllabus 2.1.2).","b":"Correct. Ambiguities are resolved first, then testability is assessed on clean criteria, and completeness last (syllabus 2.2.1, HO-2.2.1b).","c":"Incorrect. Testability cannot be judged reliably while the wording is still ambiguous (syllabus 2.2.1, HO-2.2.1b).","d":"Incorrect. Proposing new criteria before clarifying the existing ones builds on vague wording (syllabus 2.2.1, HO-2.2.1b)."},"obecne":"Each step of the chain uses a verified result of the previous step; the syllabus order is ambiguities, testability, completeness."},"cz":{"q":"<p>Product owner e-shopu dodá uživatelský scénář s akceptačními kritérii pro věrnostní program a přizná, že některá kritéria jsou vágní. Chcete pomocí řetězení promptů s lidským ověřením dosáhnout dobře formulovaných a použitelných akceptačních kritérií. Která posloupnost promptů je NEJVHODNĚJŠÍ?<\/p><ol><li>Požádat LLM, aby posoudil testovatelnost každého kritéria a netestovatelná přepsal.<\/li><li>Požádat LLM, aby našel nejednoznačné formulace ve scénáři a kritériích.<\/li><li>Požádat LLM, aby posoudil, zda kritéria pokrývají scénář úplně, a navrhl chybějící.<\/li><\/ol><p>Po každém kroku výsledek ověříte a opravíte, než pošlete další prompt.<\/p>","m":["Všechny tři kroky v jednom promptu a na konci jedna kontrola","2 – 1 – 3","1 – 2 – 3","3 – 2 – 1"],"vys":{"a":"Špatně. To není řetězení promptů; mezivýsledky se neověřují (sylabus 2.1.2).","b":"Správně. Nejdřív se vyřeší nejednoznačnosti, pak se na vyčištěných kritériích posoudí testovatelnost a nakonec úplnost (sylabus 2.2.1, HO-2.2.1b).","c":"Špatně. Testovatelnost nelze spolehlivě posoudit, dokud jsou formulace nejednoznačné (sylabus 2.2.1, HO-2.2.1b).","d":"Špatně. Navrhovat nová kritéria před vyjasněním stávajících znamená stavět na vágních formulacích (sylabus 2.2.1, HO-2.2.1b)."},"obecne":"Každý krok řetězu pracuje s ověřeným výsledkem předchozího; pořadí podle sylabu je nejednoznačnosti, testovatelnost, úplnost."},"kap":{"c":"2.2.1","nazev":"2.2.1 Testovací analýza s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.2-04","n":13,"lo":"GenAI-2.2.2","k":"K3","body":2,"vyber":1,"ok":[2],"en":{"q":"<p>A test suite of 40 test cases has priorities, risks and dependencies (some test cases prepare data for others). In a single prompt, the LLM produced an execution order sorted by risk, but several test cases were scheduled before the test cases they depend on. Which approach is MOST appropriate?<\/p>","m":["Ask the LLM for a meta prompt and use its output as the final schedule.","Repeat the same prompt until an order without violations appears.","Use prompt chaining: first let the LLM extract all dependencies and verify them manually, then ask for an order by risk that respects the verified dependencies, and verify the result again.","Remove the dependencies from the input data so the model can focus on risk."],"vys":{"a":"Incorrect. A meta prompt produces a prompt, not a verified schedule (syllabus 2.1.2).","b":"Incorrect. Repeating does not address the reasoning error and gives no assurance (syllabus 2.2.2, 2.3.2).","c":"Correct. Multi-criteria tasks benefit from decomposition with manual verification of the LLM's reasoning (syllabus 2.2.2, HO-2.2.2c).","d":"Incorrect. Dependencies are a required criterion of the schedule (syllabus 2.2.2)."},"obecne":"Test execution scheduling considers priority, risks, dependencies and resources; results must be verified to detect reasoning errors."},"cz":{"q":"<p>Testovací sada 40 testovacích případů má priority, rizika a závislosti (některé případy připravují data pro jiné). V jednom promptu LLM vytvořil pořadí provedení seřazené podle rizika, ale několik případů zařadil před případy, na kterých závisí. Který postup je NEJVHODNĚJŠÍ?<\/p>","m":["Požádat LLM o meta prompt a jeho výstup použít jako konečný harmonogram.","Opakovat stejný prompt, dokud nevyjde pořadí bez porušení.","Použít řetězení: nejdřív nechat LLM vypsat všechny závislosti a ručně je ověřit, pak požádat o pořadí podle rizika, které ověřené závislosti dodrží, a výsledek znovu ověřit.","Odstranit závislosti ze vstupních dat, aby se model mohl soustředit na riziko."],"vys":{"a":"Špatně. Meta prompt vytvoří prompt, ne ověřený harmonogram (sylabus 2.1.2).","b":"Špatně. Opakování neřeší chybu v uvažování a nedává žádnou jistotu (sylabus 2.2.2, 2.3.2).","c":"Správně. Úlohy s více kritérii těží z rozkladu s ručním ověřením uvažování modelu (sylabus 2.2.2, HO-2.2.2c).","d":"Špatně. Závislosti jsou povinné kritérium harmonogramu (sylabus 2.2.2)."},"obecne":"Plánování provedení zohledňuje prioritu, rizika, závislosti a zdroje; výsledek je nutné ověřit kvůli chybám v uvažování."},"kap":{"c":"2.2.2","nazev":"2.2.2 Návrh testů a implementace testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.3-03","n":14,"lo":"GenAI-2.2.3","k":"K3","body":2,"vyber":1,"ok":[3],"en":{"q":"<p>After a UI update, many GUI regression tests fail because button locators changed. The team plans to let an LLM-based tool adapt the scripts automatically. Which way of applying this is MOST appropriate?<\/p>","m":["Delete all failing tests and ask the LLM to generate new ones from scratch.","Stop running GUI regression tests and rely on API tests only.","Let the tool adapt any failing step automatically and suppress the original failure in the report.","Let the tool adapt locators for minor changes, log every adaptation with the old and new locator, and have a tester review the changes, especially for high-risk functions."],"vys":{"a":"Incorrect. This discards maintained tests instead of adapting them to minor changes (syllabus 2.2.3).","b":"Incorrect. The syllabus describes how GenAI helps stabilize GUI tests, not abandoning them (syllabus 2.2.3).","c":"Incorrect. Hiding failures could mask real defects; output must be checked (syllabus 2.2.3).","d":"Correct. Self-healing reduces unnecessary failures, but GenAI output must be checked according to the associated risk (syllabus 2.2.3)."},"obecne":"Self-healing and adaptive tests handle minor UI or API changes; testers must check GenAI output depending on risk."},"cz":{"q":"<p>Po úpravě UI padá mnoho GUI regresních testů, protože se změnily lokátory tlačítek. Tým chce nechat nástroj postavený na LLM skripty automaticky přizpůsobit. Který způsob použití je NEJVHODNĚJŠÍ?<\/p>","m":["Smazat všechny padající testy a požádat LLM o nové od začátku.","Přestat spouštět GUI regresní testy a spoléhat jen na API testy.","Nechat nástroj automaticky přizpůsobit každý padající krok a původní selhání v reportu potlačit.","Nechat nástroj přizpůsobit lokátory u drobných změn, každou úpravu zalogovat se starým a novým lokátorem a změny nechat zkontrolovat testerem, hlavně u rizikových funkcí."],"vys":{"a":"Špatně. Tím se zahodí udržované testy místo jejich přizpůsobení drobným změnám (sylabus 2.2.3).","b":"Špatně. Sylabus popisuje, jak GenAI pomáhá GUI testy stabilizovat, ne jak se jich vzdát (sylabus 2.2.3).","c":"Špatně. Skrývání selhání může zakrýt skutečné defekty; výstup je nutné kontrolovat (sylabus 2.2.3).","d":"Správně. Samooprava omezuje zbytečná selhání, ale výstup GenAI se musí kontrolovat podle souvisejícího rizika (sylabus 2.2.3)."},"obecne":"Samoopravné a adaptivní testy zvládají drobné změny UI a API; tester musí výstup GenAI kontrolovat podle rizika."},"kap":{"c":"2.2.3","nazev":"2.2.3 Automatizované regresní testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.4-01","n":15,"lo":"GenAI-2.2.4","k":"K3","body":2,"vyber":1,"ok":[0],"en":{"q":"<p>A test manager of an e-shop wants an LLM to warn her every morning about deviations from the test plan before they become problems. Her draft prompt:<\/p><pre>Role: Act as a test manager.\nContext: Acceptance testing of a new e-shop release, four weeks.\nInstruction: Summarize yesterday&#x27;s test results.\nInput data: Export of yesterday&#x27;s test results.\nConstraints: Keep it short and clear.\nOutput format: One paragraph of text.<\/pre><p>Which improvement BEST supports her goal?<\/p>","m":["Add the planned daily progress (executed tests, resolved defects) to the input data and change the instruction to compare actual progress with the plan and flag deviations above 10 %.","Extend the constraint to “keep it short, clear and professional”.","Change the role to “test manager with 15 years of experience in e-commerce”.","Add a chart of passed tests per day to the output format."],"vys":{"a":"Correct. Deviations from the plan can only be detected with the plan as input and an instruction to compare (syllabus 2.2.4).","b":"Incorrect. This only rephrases the existing constraint and adds no information.","c":"Incorrect. The persona adds no plan data to compare against (syllabus 2.1.1).","d":"Incorrect. A chart without plan values does not show deviations (syllabus 2.2.4)."},"obecne":"GenAI can analyze trends, predict risks and alert teams to deviations from the plan."},"cz":{"q":"<p>Test manažerka e-shopu chce, aby ji LLM každé ráno upozornil na odchylky od plánu testování dřív, než se z nich stanou problémy. Její návrh promptu:<\/p><pre>Role: Act as a test manager.\nContext: Acceptance testing of a new e-shop release, four weeks.\nInstruction: Summarize yesterday&#x27;s test results.\nInput data: Export of yesterday&#x27;s test results.\nConstraints: Keep it short and clear.\nOutput format: One paragraph of text.<\/pre><p>Která úprava NEJLÉPE podpoří její cíl?<\/p>","m":["Doplnit do vstupních dat plánovaný denní postup (provedené testy, vyřešené defekty) a změnit instrukci na porovnání skutečnosti s plánem a označení odchylek nad 10 %.","Rozšířit omezení na „stručně, jasně a profesionálně“.","Změnit roli na „test manažer s 15 lety praxe v e-commerce“.","Přidat do formátu výstupu graf prošlých testů po dnech."],"vys":{"a":"Správně. Odchylky od plánu lze odhalit jen s plánem na vstupu a instrukcí k porovnání (sylabus 2.2.4).","b":"Špatně. Jen jinými slovy opakuje existující omezení a nepřidává informaci.","c":"Špatně. Persona nepřidá data plánu, se kterými by se porovnávalo (sylabus 2.1.1).","d":"Špatně. Graf bez plánovaných hodnot odchylky neukáže (sylabus 2.2.4)."},"obecne":"GenAI umí analyzovat trendy, předvídat rizika a upozorňovat tým na odchylky od plánu."},"kap":{"c":"2.2.4","nazev":"2.2.4 Monitoring testování a řízení testování s GenAI","href":"kapitola-2/vyklad.html#oddil-2-2-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.2.5-01","n":16,"lo":"GenAI-2.2.5","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>A team must rewrite about 400 existing defect reports into a new company template. The test lead has three reports already converted correctly by hand. Which prompting technique is BEST suited?<\/p>","m":["Meta prompting to discover what a defect report is","Few-shot prompting with the three converted reports as examples","Zero-shot prompting with the instruction “use the new template”","Prompt chaining with a manual review after each sentence of every report"],"vys":{"a":"Incorrect. The task and the target format are already well known; no new prompt needs to be explored (syllabus 2.2.5).","b":"Correct. A repetitive task with a specific output format and available examples fits few-shot prompting (syllabus 2.2.5).","c":"Incorrect. Without the template or examples the model cannot reproduce the format consistently (syllabus 2.1.2).","d":"Incorrect. The task is repetitive rather than complex; such fine-grained chaining adds effort without benefit (syllabus 2.2.5)."},"obecne":"Few-shot prompting is recommended for repetitive or specific/constrained output format tasks."},"cz":{"q":"<p>Tým musí přepsat asi 400 existujících reportů o defektech do nové firemní šablony. Vedoucí testů má tři reporty, které už ručně správně převedl. Která technika promptování je NEJVHODNĚJŠÍ?<\/p>","m":["Meta prompting, aby se zjistilo, co je report o defektu","Few-shot prompting se třemi převedenými reporty jako příklady","Zero-shot prompting s instrukcí „použij novou šablonu“","Prompt chaining s ruční kontrolou po každé větě každého reportu"],"vys":{"a":"Špatně. Úloha i cílový formát jsou známé; není třeba zkoumat nový prompt (sylabus 2.2.5).","b":"Správně. Opakující se úloha s pevným formátem výstupu a dostupnými příklady se hodí pro few-shot (sylabus 2.2.5).","c":"Špatně. Bez šablony nebo příkladů model formát konzistentně nevytvoří (sylabus 2.1.2).","d":"Špatně. Úloha je spíš opakující se než složitá; tak jemné řetězení přidá práci bez přínosu (sylabus 2.2.5)."},"obecne":"Few-shot se doporučuje pro opakující se úlohy a úlohy s konkrétním nebo omezeným formátem výstupu."},"kap":{"c":"2.2.5","nazev":"2.2.5 Výběr techniky promptování","href":"kapitola-2/vyklad.html#oddil-2-2-5"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.1-04","n":17,"lo":"GenAI-2.3.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>A team evaluates an LLM by running a prompt once and calculating the metrics from that single output. Why is this approach insufficient according to the syllabus?<\/p>","m":["Because metrics are only meaningful for fine-tuned models.","Because metrics may only be calculated automatically, never by manual review.","Because GenAI is non-deterministic, so metrics must be based on statistically relevant data such as several runs.","Because only time efficiency can be measured from one output."],"vys":{"a":"Incorrect. The metrics apply to GenAI results on test tasks in general (syllabus 2.3.1).","b":"Incorrect. The syllabus allows manual reviews as well as automated comparison (syllabus 2.3.1).","c":"Correct. Given the non-deterministic nature of GenAI, metrics must be based on statistically relevant data (syllabus 2.3.1).","d":"Incorrect. All metrics can be computed from one output; the problem is that one output is not representative."},"obecne":"Metrics can be evaluated manually or automatically against a reference, and must rest on statistically relevant data."},"cz":{"q":"<p>Tým hodnotí LLM tak, že prompt spustí jednou a metriky spočítá z tohoto jediného výstupu. Proč je to podle sylabu nedostatečné?<\/p>","m":["Protože metriky mají smysl jen u doladěných (fine-tuned) modelů.","Protože metriky se smí počítat jen automaticky, nikdy ruční revizí.","Protože GenAI je nedeterministická, metriky musí vycházet ze statisticky relevantních dat, například z více běhů.","Protože z jednoho výstupu lze měřit jen time efficiency."],"vys":{"a":"Špatně. Metriky se týkají výsledků GenAI v testovacích úlohách obecně (sylabus 2.3.1).","b":"Špatně. Sylabus připouští ruční revizi i automatické porovnání (sylabus 2.3.1).","c":"Správně. Kvůli nedeterministické povaze GenAI musí metriky vycházet ze statisticky relevantních dat (sylabus 2.3.1).","d":"Špatně. Spočítat lze všechny metriky; problém je, že jeden výstup není reprezentativní."},"obecne":"Metriky lze vyhodnotit ručně nebo automaticky vůči referenci a musí stát na statisticky relevantních datech."},"kap":{"c":"2.3.1","nazev":"2.3.1 Metriky pro hodnocení výsledků GenAI v testovacích úlohách","href":"kapitola-2/vyklad.html#oddil-2-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-2.3.2-02","n":18,"lo":"GenAI-2.3.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A team has two versions of a prompt for generating test data. It runs each version ten times and compares the share of invalid partitions covered and the number of duplicate records. Which technique is this?<\/p>","m":["Prompt chaining","Output analysis","Integrate user feedback","A/B testing of prompts"],"vys":{"a":"Incorrect. Prompt chaining decomposes a task; it is not a prompt evaluation technique (syllabus 2.1.2).","b":"Incorrect. Output analysis examines errors in output to understand them, not to compare versions (syllabus 2.3.2).","c":"Incorrect. The comparison is based on metrics, not on users' opinions (syllabus 2.3.2).","d":"Correct. Multiple prompt versions are evaluated against predefined metrics (syllabus 2.3.2)."},"obecne":"A/B testing creates multiple versions of prompts and evaluates which performs better based on predefined metrics."},"cz":{"q":"<p>Tým má dvě verze promptu pro generování testovacích dat. Každou spustí desetkrát a porovná podíl pokrytých neplatných tříd a počet duplicitních záznamů. O jakou techniku jde?<\/p>","m":["Prompt chaining","Output analysis","Integrate user feedback","A/B testing of prompts"],"vys":{"a":"Špatně. Řetězení rozkládá úlohu, není to technika hodnocení promptu (sylabus 2.1.2).","b":"Špatně. Analýza výstupu zkoumá chyby, aby je pochopila, nesrovnává verze (sylabus 2.3.2).","c":"Špatně. Srovnání stojí na metrikách, ne na názorech uživatelů (sylabus 2.3.2).","d":"Správně. Víc verzí promptu se hodnotí podle předem daných metrik (sylabus 2.3.2)."},"obecne":"A/B testování vytvoří víc verzí promptu a podle předem daných metrik vyhodnotí, která dává lepší výsledky."},"kap":{"c":"2.3.2","nazev":"2.3.2 Techniky hodnocení a iterativního ladění promptů","href":"kapitola-2/vyklad.html#oddil-2-3-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.1-03","n":19,"lo":"GenAI-3.1.1","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>According to the syllabus, where do biases in LLM output originate?<\/p>","m":["From the data on which the model was trained.","From the size of the model's context window.","From the temperature setting used during inference.","From the use of prompt chaining by the tester."],"vys":{"a":"Correct. Syllabus 3.1.1 states that LLM biases originate from the training data.","b":"Incorrect. The context window determines how much text the model can consider (syllabus 1.1.2); it is not named as the origin of bias.","c":"Incorrect. Temperature influences randomness of the output (syllabus 3.1.4), not the origin of bias.","d":"Incorrect. Prompt chaining is a mitigation technique (syllabus 3.1.3), not a source of bias."},"obecne":"Example from the syllabus: models trained mainly on English data may underrepresent non-English perspectives."},"cz":{"q":"<p>Odkud podle sylabu pochází zkreslení ve výstupu LLM?<\/p>","m":["Z dat, na kterých byl model trénován.","Z velikosti kontextového okna modelu.","Z nastavení teploty během inference.","Z toho, že tester použije řetězení promptů."],"vys":{"a":"Správně. Sylabus 3.1.1 uvádí, že zkreslení pochází z trénovacích dat.","b":"Nesprávně. Kontextové okno určuje, kolik textu model zohlední (sylabus 1.1.2). Sylabus ho jako původ zkreslení neuvádí.","c":"Nesprávně. Teplota ovlivňuje náhodnost výstupu (sylabus 3.1.4), nikoli původ zkreslení.","d":"Nesprávně. Řetězení promptů je technika zmírnění (sylabus 3.1.3), ne zdroj zkreslení."},"obecne":"Příklad ze sylabu: model trénovaný hlavně na anglických datech může upozaďovat neanglické pohledy."},"kap":{"c":"3.1.1","nazev":"3.1.1 Tři druhy vad ve výstupu LLM","href":"kapitola-3/vyklad.html#oddil-3-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.2-04","n":20,"lo":"GenAI-3.1.2","k":"K3","body":2,"vyber":1,"ok":[1],"en":{"q":"<p>A test manager uses an LLM to estimate test effort.<\/p><pre>Input: 120 test cases, 4 testers, each tester executes 10 test cases per day.\nThe test environment needs 1 day of setup, which must be finished before execution starts.\n\nLLM output:\nTeam capacity: 4 x 10 = 40 test cases per day.\nExecution: 120 / 40 = 3 days.\nSince 4 testers are available, the environment setup can be shared among them\nand done in parallel with execution. Total duration: 3 days.<\/pre><p>Which statement BEST evaluates the LLM output?<\/p>","m":["It contains a hallucination, because environment setup was not part of the input.","It contains a reasoning error: the setup must precede execution, so the total duration is 4 days.","It is correct, because four testers can perform the setup in a quarter of a day.","It shows bias, because LLMs systematically produce optimistic estimates."],"vys":{"a":"Incorrect. The environment setup is explicitly stated in the input.","b":"Correct. The calculations of capacity and execution time are right, but the LLM ignores the stated dependency (cause and effect). The correct result is 1 + 3 = 4 days (syllabus 3.1.1, 3.1.2).","c":"Incorrect. The input says the setup needs 1 day and must be finished before execution; nothing indicates it can be split.","d":"Incorrect. The defect is a single logical mistake about the order of activities, not a systematic preference shown across outputs."},"obecne":"Test planning and estimation are typical tasks where LLMs make reasoning errors (syllabus 3.1.1, HO-3.1.2b)."},"cz":{"q":"<p>Testovací manažer použije LLM k odhadu pracnosti testování.<\/p><pre>Vstup: 120 testovacích případů, 4 testeři, každý provede 10 testovacích případů za den.\nTestovací prostředí potřebuje 1 den přípravy, která musí skončit před začátkem provádění.\n\nVýstup LLM:\nKapacita týmu: 4 x 10 = 40 testovacích případů za den.\nProvedení: 120 / 40 = 3 dny.\nProtože jsou k dispozici 4 testeři, přípravu prostředí si rozdělí\na udělají ji souběžně s prováděním. Celková doba: 3 dny.<\/pre><p>Které tvrzení NEJLÉPE hodnotí výstup LLM?<\/p>","m":["Obsahuje halucinaci, protože příprava prostředí ve vstupu nebyla.","Obsahuje chybu v uvažování: příprava musí předcházet provádění, celková doba je tedy 4 dny.","Je správně, protože čtyři testeři zvládnou přípravu za čtvrt dne.","Ukazuje zkreslení, protože LLM systematicky vytváří optimistické odhady."],"vys":{"a":"Nesprávně. Příprava prostředí ve vstupu výslovně je.","b":"Správně. Výpočet kapacity i doby provádění sedí, ale LLM přehlédl zadanou závislost (příčina a následek). Správně je 1 + 3 = 4 dny (sylabus 3.1.1, 3.1.2).","c":"Nesprávně. Vstup říká, že příprava trvá 1 den a musí skončit před prováděním. Nic neříká, že ji lze rozdělit.","d":"Nesprávně. Vada je jednorázová logická chyba v pořadí činností, ne systematický sklon napříč výstupy."},"obecne":"Plánování a odhad pracnosti jsou typické úlohy s chybami v uvažování (sylabus 3.1.1, HO-3.1.2b)."},"kap":{"c":"3.1.2","nazev":"3.1.2 Jak vady ve výstupu poznat","href":"kapitola-3/vyklad.html#oddil-3-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.3-03","n":21,"lo":"GenAI-3.1.3","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which of the following is an example of using a clear, interpretable data format to reduce hallucinations and reasoning errors?<\/p>","m":["Letting the LLM decide which input format it prefers.","Attaching a photo of a handwritten whiteboard sketch so that the LLM sees the original source.","Providing acceptance criteria as a table with ID, condition and expected result instead of a free-text paragraph.","Merging requirements, logs and e-mails into one long text block so that no context is lost."],"vys":{"a":"Incorrect. The tester should choose a clear format; leaving it open does not reduce ambiguity.","b":"Incorrect. Handwritten sketches are hard to interpret and ambiguous, which the syllabus advises to avoid.","c":"Correct. Structured, straightforward formats help the model focus on the essential aspects of the task (syllabus 3.1.3).","d":"Incorrect. Context should be complete, but an unstructured mixture is hard to interpret and conflicts with the advice on clear formats."},"obecne":"Avoid formats that are ambiguous or hard for GenAI to interpret (syllabus 3.1.3)."},"cz":{"q":"<p>Který z následujících příkladů ukazuje použití jasného a srozumitelného formátu dat ke snížení halucinací a chyb v uvažování?<\/p>","m":["Nechat LLM rozhodnout, jaký formát vstupu preferuje.","Přiložit fotografii ručně kresleného náčrtu z tabule, aby LLM viděl původní zdroj.","Dodat akceptační kritéria jako tabulku s ID, podmínkou a očekávaným výsledkem místo souvislého odstavce.","Spojit požadavky, logy a e-maily do jednoho dlouhého bloku textu, aby se neztratil kontext."],"vys":{"a":"Nesprávně. Jasný formát má zvolit tester. Ponechat to otevřené nejednoznačnost nesníží.","b":"Nesprávně. Ruční náčrt je těžko čitelný a nejednoznačný, a toho se má tester podle sylabu vyvarovat.","c":"Správně. Strukturované, přímočaré formáty pomáhají modelu soustředit se na podstatu úlohy (sylabus 3.1.3).","d":"Nesprávně. Kontext má být úplný, ale nestrukturovaná směs je těžko čitelná a odporuje doporučení k jasným formátům."},"obecne":"Vyhnout se formátům, které jsou nejednoznačné nebo pro generativní AI těžko čitelné (sylabus 3.1.3)."},"kap":{"c":"3.1.3","nazev":"3.1.3 Jak vadám předcházet","href":"kapitola-3/vyklad.html#oddil-3-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.1.4-02","n":22,"lo":"GenAI-3.1.4","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>What is the purpose of setting a random seed when using an LLM?<\/p>","m":["To reduce the number of tokens in the output.","To restrict the answers of the model to a specific domain, such as medicine.","To guarantee that the output is factually correct.","To make the model use the same pseudo-random sequence, which improves reproducibility."],"vys":{"a":"Incorrect. Output length is not controlled by the seed.","b":"Incorrect. A seed does not restrict topics; domain focus comes from the prompt, RAG or fine-tuning.","c":"Incorrect. A reproducible output can still contain hallucinations.","d":"Correct. Syllabus 3.1.4: a seed ensures the same pseudo-random sequence is used, which improves reproducibility."},"obecne":"Only some LLM implementations allow setting a seed (syllabus 3.1.4)."},"cz":{"q":"<p>K čemu slouží nastavení náhodného semínka (random seed) při použití LLM?<\/p>","m":["Aby snížilo počet tokenů ve výstupu.","Aby omezilo odpovědi modelu na určitou oblast, například medicínu.","Aby zaručilo, že výstup je fakticky správný.","Aby model použil stejnou pseudonáhodnou posloupnost, což zlepší opakovatelnost."],"vys":{"a":"Nesprávně. Délku výstupu semínko neřídí.","b":"Nesprávně. Semínko témata neomezuje. Zaměření na doménu dává prompt, RAG nebo fine-tuning.","c":"Nesprávně. Opakovatelný výstup může stále obsahovat halucinace.","d":"Správně. Sylabus 3.1.4: semínko zajistí stejnou pseudonáhodnou posloupnost a tím lepší opakovatelnost."},"obecne":"Nastavení semínka umožňují jen některé implementace LLM (sylabus 3.1.4)."},"kap":{"c":"3.1.4","nazev":"3.1.4 Nedeterministické chování a jak ho omezit","href":"kapitola-3/vyklad.html#oddil-3-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.1-04","n":23,"lo":"GenAI-3.2.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following is a SECURITY risk, rather than a data privacy concern, when testing with GenAI?<\/p>","m":["Attackers intentionally introduce malicious input data to mislead the LLM used in the test infrastructure.","A GenAI tool is used without complying with GDPR.","The output of the LLM accidentally reveals sensitive information.","A GenAI tool stores sensitive data without explicit consent of the user."],"vys":{"a":"Correct. Syllabus 3.2.1 lists this among the specific security risks.","b":"Incorrect. This is the data privacy concern 'compliance risks'.","c":"Incorrect. This is the data privacy concern 'unintentional data exposure'.","d":"Incorrect. This is the data privacy concern 'lack of control over data usage'."},"obecne":"Syllabus 3.2.1 separates data privacy concerns from security risks."},"cz":{"q":"<p>Které z následujících je BEZPEČNOSTNÍ riziko, a ne obava týkající se ochrany dat, při testování s generativní AI?<\/p>","m":["Útočníci úmyslně vnášejí škodlivá vstupní data, aby zmátli LLM v testovací infrastruktuře.","Nástroj generativní AI se používá bez souladu s GDPR.","Výstup LLM nechtěně odhalí citlivou informaci.","Nástroj generativní AI ukládá citlivá data bez výslovného souhlasu uživatele."],"vys":{"a":"Správně. Sylabus 3.2.1 to uvádí mezi specifickými bezpečnostními riziky.","b":"Nesprávně. To je obava o ochranu dat „riziko nesouladu s předpisy“.","c":"Nesprávně. To je obava o ochranu dat „neúmyslné vyzrazení dat“.","d":"Nesprávně. To je obava o ochranu dat „ztráta kontroly nad použitím dat“."},"obecne":"Sylabus 3.2.1 odděluje obavy o ochranu dat od bezpečnostních rizik."},"kap":{"c":"3.2.1","nazev":"3.2.1 Rizika pro ochranu dat a bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.2-04","n":24,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>During review, a tester finds that an LLM-generated test setup function downloads a shell script from an external IP address and executes it. Which attack vector is MOST likely involved?<\/p>","m":["Request manipulation","Malicious code generation","Context manipulation","Data poisoning"],"vys":{"a":"Incorrect. Request manipulation means introducing data that disrupts the AI's output during use (syllabus 3.2.2).","b":"Correct. Malicious code generation means manipulating an LLM to generate backdoors, e.g. external command calls, during use (syllabus 3.2.2). Downloading and executing code from an external address is a backdoor through external command calls.","c":"Incorrect. Context manipulation means sending requests designed to extract confidential training data (syllabus 3.2.2).","d":"Incorrect. Data poisoning means manipulating training data (syllabus 3.2.2)."},"obecne":"Generated code must be reviewed before execution (syllabus 3.2.3)."},"cz":{"q":"<p>Při revizi tester zjistí, že funkce pro přípravu testů vygenerovaná LLM stahuje shellový skript z externí IP adresy a spouští ho. Který vektor útoku je NEJSPÍŠ ve hře?<\/p>","m":["Manipulace s požadavkem (request manipulation)","Generování škodlivého kódu (malicious code generation)","Manipulace s kontextem (context manipulation)","Otrávení dat (data poisoning)"],"vys":{"a":"Nesprávně. Manipulace s požadavkem znamená vložit data, která při použití naruší výstup AI (sylabus 3.2.2).","b":"Správně. Generování škodlivého kódu znamená zmanipulovat LLM, aby při použití vytvořil zadní vrátka, např. volání externích příkazů (sylabus 3.2.2). Stažení a spuštění kódu z externí adresy jsou zadní vrátka přes volání externích příkazů.","c":"Nesprávně. Manipulace s kontextem znamená posílat požadavky, které mají z modelu vytáhnout důvěrná trénovací data (sylabus 3.2.2).","d":"Nesprávně. Otrávení dat znamená manipulaci s trénovacími daty (sylabus 3.2.2)."},"obecne":"Vygenerovaný kód je nutné před spuštěním revidovat (sylabus 3.2.3)."},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.2-08","n":25,"lo":"GenAI-3.2.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which pair correctly matches an attack vector with its description?<\/p>","m":["Context manipulation – inserting backdoors into generated code.","Malicious code generation – manipulating training data with fake ratings.","Request manipulation – introducing data, such as misleading images, that disrupts the AI's output.","Data poisoning – extracting confidential training data with very long prompts."],"vys":{"a":"Incorrect. Backdoors belong to malicious code generation; context manipulation extracts training data.","b":"Incorrect. Fake ratings in training data are data poisoning.","c":"Correct. This matches the description and example in syllabus 3.2.2.","d":"Incorrect. Extracting training data with long prompts is context manipulation."},"obecne":"Learn each vector with its goal and the syllabus example (syllabus 3.2.2)."},"cz":{"q":"<p>Která dvojice správně přiřazuje vektor útoku k jeho popisu?<\/p>","m":["Manipulace s kontextem – vložení zadních vrátek do generovaného kódu.","Generování škodlivého kódu – manipulace s trénovacími daty pomocí falešných hodnocení.","Manipulace s požadavkem – vložení dat, například zavádějících obrázků, která naruší výstup AI.","Otrávení dat – získání důvěrných trénovacích dat velmi dlouhými prompty."],"vys":{"a":"Nesprávně. Zadní vrátka patří ke generování škodlivého kódu. Manipulace s kontextem získává trénovací data.","b":"Nesprávně. Falešná hodnocení v trénovacích datech jsou otrávení dat.","c":"Správně. Odpovídá to popisu a příkladu ze sylabu 3.2.2.","d":"Nesprávně. Získání trénovacích dat dlouhými prompty je manipulace s kontextem."},"obecne":"Naučte se ke každému vektoru jeho cíl a příklad ze sylabu (sylabus 3.2.2)."},"kap":{"c":"3.2.2","nazev":"3.2.2 Zranitelnosti a útoky na generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.2.3-05","n":26,"lo":"GenAI-3.2.3","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A team uses an LLM to generate automation scripts that run in the CI pipeline with access to test databases. Which mitigation BEST reduces the risk of executing malicious generated code?<\/p>","m":["Limiting unnecessary interactions with the model.","Lowering the temperature of the LLM.","Anonymizing the test data before it is sent to the LLM.","Systematic human review of the generated scripts before they are executed."],"vys":{"a":"Incorrect. This is a best practice for energy consumption (syllabus 3.3.1).","b":"Incorrect. Temperature affects variability, not whether code contains backdoors.","c":"Incorrect. Anonymization protects personal data but does not detect malicious code.","d":"Correct. Human evaluation of the generated output is essential (syllabus 3.2.3) and catches backdoors before execution."},"obecne":"Additional strategies include systematic review, comparison with another LLM, a secure environment, audits and staying updated (syllabus 3.2.3)."},"cz":{"q":"<p>Tým používá LLM k generování automatizačních skriptů, které běží v CI s přístupem k testovacím databázím. Které opatření NEJLÉPE sníží riziko spuštění škodlivého vygenerovaného kódu?<\/p>","m":["Omezit zbytečné interakce s modelem.","Snížit teplotu LLM.","Anonymizovat testovací data před odesláním do LLM.","Systematická lidská revize vygenerovaných skriptů před jejich spuštěním."],"vys":{"a":"Nesprávně. To je osvědčený postup pro spotřebu energie (sylabus 3.3.1).","b":"Nesprávně. Teplota ovlivňuje variabilitu, ne to, zda kód obsahuje zadní vrátka.","c":"Nesprávně. Anonymizace chrání osobní údaje, ale škodlivý kód neodhalí.","d":"Správně. Lidské hodnocení výstupu je nezbytné (sylabus 3.2.3) a zachytí zadní vrátka před spuštěním."},"obecne":"Doplňková opatření: systematická revize, porovnání s jiným LLM, bezpečné prostředí, audity a sledování osvědčených postupů (sylabus 3.2.3)."},"kap":{"c":"3.2.3","nazev":"3.2.3 Jak chránit data a posílit bezpečnost","href":"kapitola-3/vyklad.html#oddil-3-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.3.1-03","n":27,"lo":"GenAI-3.3.1","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Every night, a team sends the same prompt five times for each of 2,000 regression test cases to the largest available LLM to check output consistency, even when nothing has changed. Which change would MOST reduce energy consumption while keeping the purpose?<\/p>","m":["Run the consistency check only when the prompt or model changes, and use a smaller model if it is sufficient for the task.","Increase the temperature so that fewer runs are needed.","Ask the model to return a screenshot-like image instead of text.","Add the full test logs to every prompt to give more context."],"vys":{"a":"Correct. Fewer unnecessary interactions and a model with lower resource needs reduce consumption; this reflects the impact of model usage (syllabus 3.3.1).","b":"Incorrect. A higher temperature increases variability, which would require more checking, not less.","c":"Incorrect. Image generation is far more energy-intensive than text generation.","d":"Incorrect. More tokens in the context increase computational effort (syllabus 1.1.2)."},"obecne":"Best practice: limit unnecessary model interactions (syllabus 3.3.1)."},"cz":{"q":"<p>Tým každou noc posílá největšímu dostupnému LLM stejný prompt pětkrát pro každý z 2 000 regresních testovacích případů, aby ověřil konzistenci výstupu, i když se nic nezměnilo. Která změna NEJVÍC sníží spotřebu energie a zachová účel?<\/p>","m":["Spouštět kontrolu konzistence jen při změně promptu nebo modelu a použít menší model, pokud na úlohu stačí.","Zvýšit teplotu, aby bylo potřeba méně běhů.","Požádat model o výstup v podobě obrázku místo textu.","Přidat do každého promptu celé testovací logy, aby měl model víc kontextu."],"vys":{"a":"Správně. Méně zbytečných interakcí a model s menšími nároky spotřebu sníží. Odráží to vliv způsobu použití modelu (sylabus 3.3.1).","b":"Nesprávně. Vyšší teplota zvyšuje variabilitu, kontroly by bylo potřeba víc, ne méně.","c":"Nesprávně. Generování obrázků je mnohem náročnější na energii než generování textu.","d":"Nesprávně. Víc tokenů v kontextu zvyšuje výpočetní náročnost (sylabus 1.1.2)."},"obecne":"Osvědčený postup: omezit zbytečné interakce s modelem (sylabus 3.3.1)."},"kap":{"c":"3.3.1","nazev":"3.3.1 Vliv generativní AI na spotřebu energie a emise CO₂","href":"kapitola-3/vyklad.html#oddil-3-3-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-3.4.1-05","n":28,"lo":"GenAI-3.4.1","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Why should test organizations keep track of AI regulations, standards and frameworks?<\/p>","m":["Because an organization certified to ISO/IEC 42001 no longer has to comply with GDPR.","Because AI technologies and their regulatory landscape keep evolving, including regulations, standards, national laws and best-practice frameworks.","Because the EU AI Act applies only to companies based in the United States.","Because the listed standards replace the need for defined test processes."],"vys":{"a":"Incorrect. A standard certification does not replace legal obligations.","b":"Correct. Syllabus 3.4.1 states that test organizations need to stay updated as the landscape evolves.","c":"Incorrect. The EU AI Act is a European regulation.","d":"Incorrect. The standards support responsible use of GenAI; they do not replace test processes."},"obecne":"Addressing GenAI risks should consider regulations, standards and best-practice frameworks (syllabus 3.4)."},"cz":{"q":"<p>Proč mají testovací organizace sledovat předpisy, standardy a rámce pro AI?<\/p>","m":["Protože organizace certifikovaná podle ISO/IEC 42001 už nemusí dodržovat GDPR.","Protože se technologie AI i oblast předpisů stále vyvíjejí, včetně předpisů, standardů, národních zákonů a rámců osvědčených postupů.","Protože EU AI Act platí jen pro firmy se sídlem v USA.","Protože uvedené standardy nahrazují potřebu definovaných testovacích procesů."],"vys":{"a":"Nesprávně. Certifikace podle standardu nenahrazuje zákonné povinnosti.","b":"Správně. Sylabus 3.4.1 uvádí, že testovací organizace musí držet krok s vývojem.","c":"Nesprávně. EU AI Act je evropský předpis.","d":"Nesprávně. Standardy podporují odpovědné použití generativní AI, testovací procesy nenahrazují."},"obecne":"Při řešení rizik generativní AI je třeba brát v úvahu předpisy, standardy a rámce osvědčených postupů (sylabus 3.4)."},"kap":{"c":"3.4.1","nazev":"3.4.1 Předpisy, standardy a rámce relevantní pro generativní AI v testování","href":"kapitola-3/vyklad.html#oddil-3-4-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.1-03","n":29,"lo":"GenAI-4.1.1","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>The back-end of an LLM-powered test tool integrates several data sources. Which of the following statements correctly describes the role of these data sources?<\/p>","m":["A vector database stores test execution results in tables so that exact queries such as counts of failed tests can be answered.","A vector database handles user authentication, while a relational database prepares the prompt.","A relational database holds structured data such as existing test cases, while a vector database enables retrieval of related content by meaning using embeddings.","A relational database provides semantic retrieval of related content by comparing embeddings."],"vys":{"a":"Incorrect. Tables and exact queries describe a relational database. A vector database stores high-dimensional vectors for similarity search (4.1.1, 4.1.2).","b":"Incorrect. Authentication and prompt preparation are functions of the back-end, not of the databases (4.1.1).","c":"Correct. Section 4.1.1 lists relational databases for structured data used in testing, such as test cases, and vector databases for semantic retrieval of related content using embeddings.","d":"Incorrect. The roles are swapped. Semantic retrieval using embeddings is the purpose of a vector database (4.1.1)."},"obecne":"Relational database: structured data, exact queries. Vector database: embeddings, retrieval by semantic similarity."},"cz":{"q":"<p>Back-end testovacího nástroje postaveného na LLM spojuje několik zdrojů dat. Které z následujících tvrzení správně popisuje roli těchto zdrojů?<\/p>","m":["Vektorová databáze ukládá výsledky běhů testů do tabulek, aby šlo odpovídat na přesné dotazy, například kolik testů selhalo.","Vektorová databáze zajišťuje autentizaci uživatelů a relační databáze připravuje prompt.","Relační databáze drží strukturovaná data, například existující testovací případy, a vektorová databáze umožňuje vyhledat související obsah podle významu pomocí embeddingů.","Relační databáze umožňuje sémantické vyhledávání souvisejícího obsahu porovnáváním embeddingů."],"vys":{"a":"Špatně. Tabulky a přesné dotazy popisují relační databázi. Vektorová databáze ukládá vektory pro vyhledávání podle podobnosti (4.1.1, 4.1.2).","b":"Špatně. Autentizace a příprava promptu jsou funkce back-endu, ne databází (4.1.1).","c":"Správně. Oddíl 4.1.1 uvádí relační databáze pro strukturovaná data, například testovací případy, a vektorové databáze pro sémantické vyhledávání pomocí embeddingů.","d":"Špatně. Role jsou prohozené. Sémantické vyhledávání pomocí embeddingů je úloha vektorové databáze (4.1.1)."},"obecne":"Relační databáze: strukturovaná data a přesné dotazy. Vektorová databáze: embeddingy a vyhledávání podle významu."},"kap":{"c":"4.1.1","nazev":"4.1.1 Architektonické komponenty a koncepty","href":"kapitola-4/vyklad.html#oddil-4-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.2-02","n":30,"lo":"GenAI-4.1.2","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A team prepares its test basis documents for a RAG system. Consider the following preprocessing steps:<\/p><ol><li>Store the embeddings in a vector database<\/li><li>Split the documents into chunks<\/li><li>Encode each chunk into an embedding<\/li><li>Clean and process each chunk<\/li><\/ol><p>Which of the following represents the correct order?<\/p>","m":["2 – 3 – 4 – 1","4 – 2 – 1 – 3","2 – 4 – 1 – 3","2 – 4 – 3 – 1"],"vys":{"a":"Incorrect. Each chunk is cleaned and processed before it is encoded into an embedding (4.1.2).","b":"Incorrect. Cleaning is done on chunks, so splitting comes first. Storing must also follow encoding (4.1.2).","c":"Incorrect. Embeddings can only be stored after they have been created (4.1.2).","d":"Correct. According to 4.1.2, documents are broken into chunks, each chunk is cleaned and processed, encoded into an embedding, and the embeddings are stored in a vector database."},"obecne":"Preprocessing order: chunk, clean and process, embed, store."},"cz":{"q":"<p>Tým připravuje dokumenty testovací báze pro systém RAG. Uvažujte tyto kroky předzpracování:<\/p><ol><li>Uložit embeddingy do vektorové databáze<\/li><li>Rozdělit dokumenty na části<\/li><li>Převést každou část na embedding<\/li><li>Vyčistit a zpracovat každou část<\/li><\/ol><p>Které pořadí je správné?<\/p>","m":["2 – 3 – 4 – 1","4 – 2 – 1 – 3","2 – 4 – 1 – 3","2 – 4 – 3 – 1"],"vys":{"a":"Špatně. Každá část se vyčistí a zpracuje dřív, než se převede na embedding (4.1.2).","b":"Špatně. Čistí se jednotlivé části, takže rozdělení je první. Uložení musí následovat až po převodu (4.1.2).","c":"Špatně. Embeddingy lze uložit až poté, co vzniknou (4.1.2).","d":"Správně. Podle 4.1.2 se dokumenty rozdělí na části, každá část se vyčistí a zpracuje, převede na embedding a embeddingy se uloží do vektorové databáze."},"obecne":"Pořadí předzpracování: rozdělit, vyčistit a zpracovat, převést na embedding, uložit."},"kap":{"c":"4.1.2","nazev":"4.1.2 Retrieval-Augmented Generation (RAG)","href":"kapitola-4/vyklad.html#oddil-4-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.1.3-05","n":31,"lo":"GenAI-4.1.3","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following statements correctly contrasts autonomous and semi-autonomous LLM-powered agents?<\/p>","m":["Autonomous agents operate independently with minimal human intervention, using predefined rules, reinforcement learning and adaptive feedback loops, whereas semi-autonomous agents work with periodic human oversight to ensure the output meets user-defined goals.","Autonomous agents are always part of a multi-agent architecture, whereas semi-autonomous agents always work alone.","Autonomous agents do not produce hallucinations because their adaptive feedback loops correct every error, whereas semi-autonomous agents need human review for this reason.","Semi-autonomous agents cannot invoke tools and therefore only provide recommendations, whereas autonomous agents can act on external systems."],"vys":{"a":"Correct. This matches the two degrees of autonomy described in section 4.1.3.","b":"Incorrect. The degree of autonomy and the multi-agent architecture are independent concepts in 4.1.3. Both types can work alone or together with other agents.","c":"Incorrect. All LLM-powered agents can produce hallucinations, reasoning errors and biases (4.1.3).","d":"Incorrect. Both types are agents and can invoke tools. The difference lies in the level of human oversight (4.1.3)."},"obecne":"The degree of autonomy is defined by how much a human is involved."},"cz":{"q":"<p>Které z následujících tvrzení správně porovnává autonomní a poloautonomní agenty postavené na LLM?<\/p>","m":["Autonomní agenti pracují samostatně s minimálním zásahem člověka a využívají předem daná pravidla, učení posilováním a adaptivní zpětnovazební smyčky. Poloautonomní agenti pracují s pravidelným lidským dohledem, aby výstup odpovídal cílům uživatele.","Autonomní agenti jsou vždy součástí multiagentní architektury, kdežto poloautonomní agenti pracují vždy sami.","Autonomní agenti nehalucinují, protože adaptivní zpětnovazební smyčky opraví každou chybu. Poloautonomní agenti kvůli tomu potřebují lidskou kontrolu.","Poloautonomní agenti nemohou volat nástroje, a proto jen doporučují. Autonomní agenti umí jednat v externích systémech."],"vys":{"a":"Správně. Odpovídá to dvěma úrovním autonomie popsaným v oddílu 4.1.3.","b":"Špatně. Úroveň autonomie a multiagentní architektura jsou v 4.1.3 nezávislé pojmy. Oba typy mohou pracovat samostatně i s dalšími agenty.","c":"Špatně. Všichni agenti postavení na LLM mohou halucinovat, chybovat v uvažování a být zkreslení (4.1.3).","d":"Špatně. Oba typy jsou agenti a mohou volat nástroje. Liší se mírou lidského dohledu (4.1.3)."},"obecne":"Úroveň autonomie určuje míra zapojení člověka."},"kap":{"c":"4.1.3","nazev":"4.1.3 Agenti postavení na LLM v automatizaci testovacích procesů","href":"kapitola-4/vyklad.html#oddil-4-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.1-02","n":32,"lo":"GenAI-4.2.1","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following statements correctly describes a difference between fine-tuning and RAG?<\/p>","m":["Both fine-tuning and RAG modify the weights of the model, but RAG does so only for the retrieved documents.","Fine-tuning updates the model's parameters through further training on a targeted dataset, whereas RAG supplies retrieved data as context at inference time without changing the model.","Fine-tuning changes only the system prompt of the model, whereas RAG retrains the model on enterprise data.","RAG trains the embedding layer of the LLM on enterprise documents, whereas fine-tuning does not involve any training."],"vys":{"a":"Incorrect. RAG does not modify the model's weights. It adds retrieved information to the prompt (4.1.2).","b":"Correct. Fine-tuning involves further training the model on a targeted dataset (4.2.1, Appendix D: updating LLM weights). RAG retrieves relevant chunks at runtime and feeds them to the LLM (4.1.2).","c":"Incorrect. Changing the system prompt is prompt engineering, and RAG does not retrain the model (2.1, 4.1.2).","d":"Incorrect. RAG uses a pre-trained embedding model to encode chunks but does not train the LLM. Fine-tuning is a training process (4.1.2, 4.2.1)."},"obecne":"Fine-tuning changes the model. RAG changes what the model receives in the prompt."},"cz":{"q":"<p>Které z následujících tvrzení správně popisuje rozdíl mezi fine-tuningem a RAG?<\/p>","m":["Fine-tuning i RAG upravují váhy modelu, RAG to ale dělá jen pro vyhledané dokumenty.","Fine-tuning upravuje parametry modelu dalším tréninkem na cílené datové sadě, kdežto RAG dodává vyhledaná data jako kontext při inferenci a model nemění.","Fine-tuning mění jen systémový prompt modelu, kdežto RAG model znovu trénuje na firemních datech.","RAG trénuje vrstvu embeddingů LLM na firemních dokumentech, kdežto fine-tuning žádný trénink nezahrnuje."],"vys":{"a":"Špatně. RAG váhy modelu nemění. Přidává vyhledané informace do promptu (4.1.2).","b":"Správně. Fine-tuning znamená další trénink modelu na cílené datové sadě (4.2.1, Appendix D: úprava vah LLM). RAG za běhu vyhledá relevantní části a předá je LLM (4.1.2).","c":"Špatně. Změna systémového promptu je prompt engineering a RAG model netrénuje (2.1, 4.1.2).","d":"Špatně. RAG používá k převodu částí předtrénovaný model pro embeddingy, ale LLM netrénuje. Fine-tuning je trénink (4.1.2, 4.2.1)."},"obecne":"Fine-tuning mění model. RAG mění to, co model dostane v promptu."},"kap":{"c":"4.2.1","nazev":"4.2.1 Fine-tuning LLM pro testovací úlohy","href":"kapitola-4/vyklad.html#oddil-4-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-4.2.2-01","n":33,"lo":"GenAI-4.2.2","k":"K2","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>An organization decides to activate the GenAI features of its commercial test management tool to generate test case proposals from requirements.<\/p><p>Which LLMOps consideration is specific to this approach, in addition to data privacy, security and operational cost?<\/p>","m":["Choosing between an LLM-as-a-Service platform and an open-source LLM deployed for a chatbot.","None, because the tool provider is responsible for all LLMOps decisions.","Evaluating the data security and performance assurances offered by the test tool provider, supported by a cost-benefit analysis and risk assessment.","Planning GPU capacity, data storage and staff training for developing and hosting its own model."],"vys":{"a":"Incorrect. This choice is described for the AI chatbot approach (4.2.2).","b":"Incorrect. The organization still has to assess the provider and the risks. LLMOps decisions depend on the chosen approach, but they do not disappear (4.2.2).","c":"Correct. Section 4.2.2 states that for test tools with GenAI capabilities, organizations must also evaluate the data security and performance assurances of the provider, and that a thorough cost-benefit analysis and risk assessment is required.","d":"Incorrect. Planning computational resources, storage and staff training is emphasized for in-house development (4.2.2)."},"obecne":"Each of the three approaches in 4.2.2 has its own emphasis."},"cz":{"q":"<p>Organizace se rozhodne zapnout funkce generativní AI ve svém komerčním nástroji pro správu testů, aby generovaly návrhy testovacích případů z požadavků.<\/p><p>Která úvaha LLMOps je pro tento přístup specifická, vedle ochrany dat, bezpečnosti a provozních nákladů?<\/p>","m":["Vybrat mezi platformou LLM jako služba a open-source LLM nasazeným pro chatbot.","Žádná, protože za všechna rozhodnutí LLMOps odpovídá poskytovatel nástroje.","Posoudit záruky poskytovatele testovacího nástroje k bezpečnosti dat a výkonu, podložené analýzou nákladů a přínosů a posouzením rizik.","Naplánovat kapacitu GPU, úložiště dat a školení lidí pro vývoj a provoz vlastního modelu."],"vys":{"a":"Špatně. Tuto volbu sylabus popisuje u přístupu s AI chatbotem (4.2.2).","b":"Špatně. Organizace musí poskytovatele i rizika posoudit sama. Rozhodnutí LLMOps závisí na přístupu, ale nemizí (4.2.2).","c":"Správně. Podle 4.2.2 musí organizace u testovacích nástrojů s GenAI navíc posoudit záruky poskytovatele k bezpečnosti dat a výkonu a provést důkladnou analýzu nákladů a přínosů a posouzení rizik.","d":"Špatně. Plánování výpočetního výkonu, úložiště a školení sylabus zdůrazňuje u vlastního vývoje (4.2.2)."},"obecne":"Každý ze tří přístupů v 4.2.2 má jiný důraz."},"kap":{"c":"4.2.2","nazev":"4.2.2 LLMOps při nasazení a správě LLM pro testování","href":"kapitola-4/vyklad.html#oddil-4-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.1-02","n":34,"lo":"GenAI-5.1.1","k":"K1","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A tester copies extracts from a customer database into a free online chatbot using a personal account to get help with a data conversion defect. The tool has not been reviewed by the organization.<\/p><p>Which risk of shadow AI does this situation MOST directly illustrate?<\/p>","m":["Reasoning errors, because the chatbot may misunderstand the conversion logic","Non-deterministic behavior, because the chatbot may give different answers each time","Vague intellectual property, because the chatbot output may be protected by copyright","Information security and data privacy weaknesses, because personal tools may lack robust security and lead to data breaches"],"vys":{"a":"Incorrect. Reasoning errors are a general GenAI risk from section 3.1, not one of the shadow AI risks in section 5.1.1.","b":"Incorrect. Non-deterministic behavior is a property of LLMs in general, not a shadow AI risk listed in section 5.1.1.","c":"Incorrect. Intellectual property may also be a concern, but the most direct risk here is that customer data leaves the protected environment.","d":"Correct. Section 5.1.1 states that personal AI tools may lack robust security, leading to potential data breaches. Customer data in a personal account is the typical example."},"obecne":"When sensitive data is entered into an unapproved personal tool, the main shadow AI risk is the information security and data privacy weakness (section 5.1.1)."},"cz":{"q":"<p>Tester zkopíruje výňatky ze zákaznické databáze do volného online chatbotu přes osobní účet, aby mu pomohl s defektem při konverzi dat. Organizace nástroj neprověřila.<\/p><p>Které riziko stínové AI tato situace ilustruje NEJPŘÍMĚJI?<\/p>","m":["Chyby v uvažování, protože chatbot může logice konverze špatně porozumět","Nedeterministické chování, protože chatbot může pokaždé odpovědět jinak","Nejasné duševní vlastnictví, protože výstup chatbotu může být chráněn autorským právem","Slabiny v informační bezpečnosti a ochraně dat, protože osobní nástroje nemusí být dobře zabezpečené a hrozí únik dat"],"vys":{"a":"Špatně. Chyby v uvažování jsou obecné riziko GenAI z oddílu 3.1, ne riziko stínové AI z 5.1.1.","b":"Špatně. Nedeterministické chování je obecná vlastnost LLM, ne riziko stínové AI z 5.1.1.","c":"Špatně. Duševní vlastnictví může hrát roli, ale nejpřímějším rizikem je, že zákaznická data opustila chráněné prostředí.","d":"Správně. Oddíl 5.1.1 uvádí, že osobní AI nástroje nemusí mít dostatečné zabezpečení a hrozí únik dat. Zákaznická data v osobním účtu jsou typický příklad."},"obecne":"Když se citlivá data vloží do neschváleného osobního nástroje, hlavním rizikem stínové AI je slabina v informační bezpečnosti a ochraně dat (5.1.1)."},"kap":{"c":"5.1.1","nazev":"5.1.1 Rizika stínové AI","href":"kapitola-5/vyklad.html#oddil-5-1-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.2-04","n":35,"lo":"GenAI-5.1.2","k":"K2","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>An organization has trained its testers and introduced an LLM for test case generation. After six months, management asks whether the investment has improved test productivity, but nobody can answer.<\/p><p>Which aspect of the GenAI strategy was MOST likely neglected?<\/p>","m":["Collecting specific metrics to measure the effectiveness of GenAI results","Establishing transparency obligations for generated testware","Ensuring compatibility of the LLM with existing test infrastructure","Selecting an LLM that supports multimodal input"],"vys":{"a":"Correct. Section 5.1.2 requires collecting specific metrics (see 2.3.1) to measure the effectiveness of GenAI results. Without them the question about productivity cannot be answered.","b":"Incorrect. Transparency tells readers what was AI-generated but does not measure effectiveness.","c":"Incorrect. Infrastructure compatibility affects whether the LLM can be integrated, not whether the benefit can be shown.","d":"Incorrect. Multimodal input is a functional capability considered in model selection (5.1.3), not a way to evaluate benefits."},"obecne":"Measurable objectives need metrics; otherwise the organization cannot tell whether GenAI adds value (section 5.1.2)."},"cz":{"q":"<p>Organizace proškolila testery a zavedla LLM pro generování testovacích případů. Po půl roce se vedení ptá, jestli investice zvýšila produktivitu testování, ale nikdo neumí odpovědět.<\/p><p>Který aspekt strategie GenAI byl NEJSPÍŠ zanedbán?<\/p>","m":["Sběr konkrétních metrik, které měří účinnost výsledků GenAI","Zavedení povinností transparentnosti pro vygenerovaný testware","Zajištění kompatibility LLM se stávající testovací infrastrukturou","Výběr LLM, který podporuje multimodální vstup"],"vys":{"a":"Správně. Oddíl 5.1.2 požaduje sbírat konkrétní metriky (viz 2.3.1), které měří účinnost výsledků GenAI. Bez nich nejde na otázku o produktivitě odpovědět.","b":"Špatně. Transparentnost říká čtenáři, co vytvořila AI, ale účinnost neměří.","c":"Špatně. Kompatibilita s infrastrukturou ovlivňuje, jestli jde LLM zapojit, ne jestli jde přínos prokázat.","d":"Špatně. Multimodální vstup je funkční schopnost posuzovaná při výběru modelu (5.1.3), ne způsob vyhodnocení přínosu."},"obecne":"Měřitelné cíle potřebují metriky, jinak organizace nepozná, jestli GenAI přináší hodnotu (5.1.2)."},"kap":{"c":"5.1.2","nazev":"5.1.2 Klíčové aspekty strategie GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.3-02","n":36,"lo":"GenAI-5.1.3","k":"K2","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>A team wants an LLM to produce test cases in the organization's specific format and terminology. The team has several thousand historical user stories with matching approved test cases.<\/p><p>Which selection criterion is MOST relevant to this need?<\/p>","m":["Context window size, because a larger window removes the need for domain-specific data","Fine-tuning potential, because it should be evaluated whether the model can usefully be fine-tuned with domain-specific data","Community and support, because an active community will provide the organization's test case format","Recurring cost, because historical data reduces licensing fees"],"vys":{"a":"Incorrect. Context window size is a technical feature, not one of the four criteria, and it does not replace domain adaptation.","b":"Correct. Section 5.1.3 describes fine-tuning potential as evaluating whether it is possible and useful to fine-tune the model with domain-specific data to increase accuracy and relevance in specialized contexts.","c":"Incorrect. Community and support help with implementation and troubleshooting, not with the organization's own format.","d":"Incorrect. Historical data does not reduce licensing fees; recurring cost is a different criterion."},"obecne":"Organization-specific format and terminology with available domain data point to the fine-tuning potential criterion (sections 5.1.3 and 4.2.1)."},"cz":{"q":"<p>Tým chce, aby LLM vytvářel testovací případy ve specifickém formátu a terminologii organizace. Tým má několik tisíc historických uživatelských scénářů s odpovídajícími schválenými testovacími případy.<\/p><p>Které kritérium výběru je pro tuto potřebu NEJVÍC relevantní?<\/p>","m":["Velikost kontextového okna, protože větší okno odstraní potřebu doménových dat","Potenciál pro doladění, protože je třeba posoudit, jestli model jde užitečně doladit na doménových datech","Komunita a podpora, protože aktivní komunita dodá formát testovacích případů organizace","Opakované náklady, protože historická data snižují licenční poplatky"],"vys":{"a":"Špatně. Velikost kontextového okna je technická vlastnost, ne jedno ze čtyř kritérií, a doménové přizpůsobení nenahradí.","b":"Správně. Oddíl 5.1.3 popisuje potenciál pro doladění jako posouzení, jestli je možné a užitečné model doladit na doménových datech kvůli přesnosti a relevanci ve specializovaném kontextu.","c":"Špatně. Komunita a podpora pomáhají s nasazením a řešením problémů, ne s vlastním formátem organizace.","d":"Špatně. Historická data licenční poplatky nesnižují, opakované náklady jsou jiné kritérium."},"obecne":"Specifický formát a terminologie organizace spolu s dostupnými doménovými daty ukazují na kritérium potenciálu pro doladění (5.1.3, 4.2.1)."},"kap":{"c":"5.1.3","nazev":"5.1.3 Výběr LLM/SLM pro testovací úlohy","href":"kapitola-5/vyklad.html#oddil-5-1-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.1.4-03","n":37,"lo":"GenAI-5.1.4","k":"K1","body":1,"vyber":1,"ok":[2],"en":{"q":"<p>Which statement about the phases of GenAI adoption is consistent with the syllabus?<\/p>","m":["The adoption is complete when the Initiation and usage definition phase ends","The phases apply only to test automation, not to other test activities","Different use cases can be in different phases at the same time","All use cases must complete Discovery before any use case can enter the next phase"],"vys":{"a":"Incorrect. The third phase, Utilization and iteration, follows and includes continuous monitoring and measurement.","b":"Incorrect. The phases apply to GenAI adoption in the test organization in general; the syllabus example compares test report analysis with test automation.","c":"Correct. Section 5.1.4 states that the phases can run in parallel for different use cases, for example test report analysis may be further along than test automation.","d":"Incorrect. The syllabus explicitly allows parallel phases for different use cases."},"obecne":"Phases belong to use cases, not to the whole organization at once; they can run in parallel (section 5.1.4)."},"cz":{"q":"<p>Které tvrzení o fázích zavedení GenAI odpovídá sylabu?<\/p>","m":["Zavedení je dokončeno koncem fáze Initiation and usage definition","Fáze se týkají jen automatizace testů, ne jiných testovacích činností","Různé případy použití mohou být současně v různých fázích","Všechny případy použití musí dokončit Discovery, než kterýkoli z nich postoupí do další fáze"],"vys":{"a":"Špatně. Následuje třetí fáze Utilization and iteration s průběžným monitoringem a měřením.","b":"Špatně. Fáze se týkají zavedení GenAI v testovací organizaci obecně. Příklad v sylabu porovnává analýzu reportů z testování s automatizací testů.","c":"Správně. Oddíl 5.1.4 říká, že fáze mohou běžet souběžně pro různé případy použití, například analýza reportů z testování může být dál než automatizace testů.","d":"Špatně. Sylabus souběh fází pro různé případy použití výslovně připouští."},"obecne":"Fáze patří případům použití, ne celé organizaci najednou, a mohou běžet souběžně (5.1.4)."},"kap":{"c":"5.1.4","nazev":"5.1.4 Fáze zavedení GenAI v testování","href":"kapitola-5/vyklad.html#oddil-5-1-4"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.1-05","n":38,"lo":"GenAI-5.2.1","k":"K2","body":1,"vyber":1,"ok":[3],"en":{"q":"<p>A tester's first prompt produces test cases that miss negative scenarios. The tester adds examples of invalid inputs and an explicit instruction to include boundary values, then compares the new output with the previous one.<\/p><p>Which key competency from the syllabus is the tester applying?<\/p>","m":["Data sanitization","Establishing AI governance frameworks","Selecting right-sized models","Prompt refinement"],"vys":{"a":"Incorrect. No sensitive data is being removed or masked.","b":"Incorrect. AI governance frameworks are a test manager responsibility in section 5.2.3.","c":"Incorrect. The tester is not changing the model, only the prompt.","d":"Correct. Section 5.2.1 lists understanding prompt refinement techniques as a key competency; improving the prompt step by step based on the output is exactly that."},"obecne":"Key competencies in 5.2.1: assessing LLM capabilities, prompt refinement and evaluation of AI-generated testware."},"cz":{"q":"<p>První prompt testera dá testovací případy bez negativních scénářů. Tester doplní příklady neplatných vstupů a výslovný pokyn zahrnout hraniční hodnoty. Pak porovná nový výstup s předchozím.<\/p><p>Kterou hlavní kompetenci ze sylabu tester uplatňuje?<\/p>","m":["Sanitizaci dat","Zavádění rámců pro správu a řízení AI","Výběr modelů přiměřené velikosti","Zpřesňování promptů (prompt refinement)"],"vys":{"a":"Špatně. Žádná citlivá data se neodstraňují ani nemaskují.","b":"Špatně. Rámce pro správu a řízení AI jsou podle 5.2.3 odpovědnost test manažera.","c":"Špatně. Tester nemění model, jen prompt.","d":"Správně. Oddíl 5.2.1 uvádí porozumění technikám zpřesňování promptů jako hlavní kompetenci. Postupné vylepšování promptu podle výstupu je přesně to."},"obecne":"Hlavní kompetence v 5.2.1: posouzení schopností LLM, zpřesňování promptů a hodnocení testwaru od AI."},"kap":{"c":"5.2.1","nazev":"5.2.1 Dovednosti a znalosti pro testování s GenAI","href":"kapitola-5/vyklad.html#oddil-5-2-1"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.2-04","n":39,"lo":"GenAI-5.2.2","k":"K1","body":1,"vyber":1,"ok":[0],"en":{"q":"<p>Which of the following is a strategy for cultivating GenAI skills in test teams that is described in the syllabus?<\/p>","m":["Practicing with various LLMs/SLMs as part of a hands-on approach","Standardizing on a single LLM and training testers only on its user interface","Assigning all GenAI work to one expert so that others do not need training","Delaying any practical use until all testers have passed a theoretical exam"],"vys":{"a":"Correct. Section 5.2.2 says a hands-on approach is essential and includes practicing with various LLMs/SLMs.","b":"Incorrect. The syllabus recommends practicing with various LLMs/SLMs, not training on a single tool's interface.","c":"Incorrect. The syllabus emphasizes sharing know-how within the organization and peer learning.","d":"Incorrect. The syllabus emphasizes practical skills and gradual integration into daily work, not theory first."},"obecne":"Section 5.2.2: hands-on approach, various LLMs/SLMs, structured learning paths, sharing, guided exercises, peer learning, gradual integration, prompt patterns, communities of practice."},"cz":{"q":"<p>Která z následujících možností je strategií pro pěstování GenAI dovedností v testovacích týmech popsanou v sylabu?<\/p>","m":["Praxe s různými LLM/SLM jako součást praktického přístupu","Standardizace na jeden LLM a školení testerů jen na jeho uživatelské rozhraní","Přidělení veškeré práce s GenAI jednomu expertovi, aby ostatní nepotřebovali školení","Odložení praktického použití, dokud všichni testeři nesloží teoretickou zkoušku"],"vys":{"a":"Správně. Oddíl 5.2.2 říká, že praktický přístup je nezbytný a zahrnuje praxi s různými LLM/SLM.","b":"Špatně. Sylabus doporučuje praxi s různými modely, ne školení na rozhraní jednoho nástroje.","c":"Špatně. Sylabus zdůrazňuje sdílení know-how v organizaci a učení od kolegů.","d":"Špatně. Sylabus zdůrazňuje praktické dovednosti a postupné zapojení do každodenní práce, ne nejdřív teorii."},"obecne":"Oddíl 5.2.2: praktický přístup, různé LLM/SLM, strukturované vzdělávací cesty, sdílení, řízená cvičení, peer learning, postupné zapojení, vzory promptů, komunity praxe."},"kap":{"c":"5.2.2","nazev":"5.2.2 Budování schopností GenAI v testovacích týmech","href":"kapitola-5/vyklad.html#oddil-5-2-2"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""},{"id":"CG-5.2.3-02","n":40,"lo":"GenAI-5.2.3","k":"K1","body":1,"vyber":1,"ok":[1],"en":{"q":"<p>Which of the following is a new responsibility of test managers when a test organization adopts GenAI, according to the syllabus?<\/p>","m":["Writing all prompts for the test team personally","AI-based risk management","Replacing human test reviews with automated AI reviews","Retraining the foundation model on the organization's data"],"vys":{"a":"Incorrect. Prompt refinement and prompt libraries are tester tasks; the manager does not write all prompts.","b":"Correct. Section 5.2.3 lists the development of an AI-based test strategy, AI-based risk management, and monitoring and control of AI-based test processes as updated test manager responsibilities.","c":"Incorrect. The syllabus emphasizes balancing human and AI capabilities and review of AI output, not replacing human review.","d":"Incorrect. Retraining a foundation model is not a test manager responsibility in section 5.2.3."},"obecne":"Test manager additions: AI-based test strategy, AI-based risk management, monitoring and control of AI-based test processes (section 5.2.3)."},"cz":{"q":"<p>Která z následujících možností je podle sylabu novou odpovědností test manažera, když testovací organizace zavádí GenAI?<\/p>","m":["Osobně psát všechny prompty pro testovací tým","Řízení rizik spojených s AI (AI-based risk management)","Nahradit lidské revize testů automatickými revizemi AI","Přetrénovat základní model na datech organizace"],"vys":{"a":"Špatně. Zpřesňování promptů a knihovny promptů jsou úlohy testerů, manažer nepíše všechny prompty.","b":"Správně. Oddíl 5.2.3 uvádí jako rozšířené odpovědnosti test manažera vytvoření testovací strategie založené na AI, řízení rizik spojených s AI a monitoring a řízení testovacích procesů založených na AI.","c":"Špatně. Sylabus zdůrazňuje rovnováhu lidí a AI a revizi AI výstupu, ne nahrazení lidské revize.","d":"Špatně. Přetrénování základního modelu není podle 5.2.3 odpovědnost test manažera."},"obecne":"Nové u test manažera: strategie založená na AI, řízení rizik AI, monitoring a řízení AI procesů (5.2.3)."},"kap":{"c":"5.2.3","nazev":"5.2.3 Vývoj testovacích procesů v organizaci podporované AI","href":"kapitola-5/vyklad.html#oddil-5-2-3"},"zdroj":"vlastní cvičná otázka","oficialni":false,"navic":false,"pozn":""}]};
